'use strict';

// MODULES //

import { assign as kernelSincosf } from '@stdlib/math-base-special-kernel-sincosf';
import copysignf from '@stdlib/math-base-special-copysignf';
import f32 from '@stdlib/number-float64-base-to-float32';
import float32ToUint32 from '@stdlib/number-float32-base-to-uint32';
import toWordf from '@stdlib/number-float32-base-to-word';
import fromWordf from '@stdlib/number-float32-base-from-word';
import FLOAT32_SIGN_MASK from '@stdlib/constants-float32-sign-mask';
import FLOAT32_ABS_MASK from '@stdlib/constants-float32-abs-mask';
import FLOAT32_EXPONENT_MASK from '@stdlib/constants-float32-exponent-mask';
import FLOAT32_EXPONENT_BIAS from '@stdlib/constants-float32-exponent-bias';
import FLOAT32_NUM_SIGNIFICAND_BITS from '@stdlib/constants-float32-num-significand-bits';
import FLOAT32_SIGNIFICAND_MASK from '@stdlib/constants-float32-significand-mask';
import PI from '@stdlib/constants-float64-pi';


// VARIABLES //

// 1 => 0 01111111 00000000000000000000000 => 0x3f800000 = 1065353216
var ONE_WORD = 0x3f800000 >>> 0; // asm type annotation

// 1/2 = 0.5 => 0 01111110 00000000000000000000000 => 0x3f000000 = 1056964608
var HALF_WORD = 0x3f000000 >>> 0; // asm type annotation

// 1/4 = 0.25 => 0 01111101 00000000000000000000000 => 0x3e800000 = 1048576000
var QUARTER_WORD = 0x3e800000 >>> 0; // asm type annotation

// 3/4 = 0.75 => 0 01111110 10000000000000000000000 => 0x3f400000 = 1061158912
var THREE_QUARTER_WORD = 0x3f400000 >>> 0; // asm type annotation

// 2^-14 = 0.00006103515625 => 0 01110001 00000000000000000000000 => 0x38800000 = 947912704
var SMALL_WORD = 0x38800000 >>> 0; // asm type annotation

// 2^23 = 8388608 => 0 10010110 00000000000000000000000 => 0x4b000000 = 1258291200
var TWO_23_WORD = 0x4b000000 >>> 0; // asm type annotation

// 2^24 = 16777216 => 0 10010111 00000000000000000000000 => 0x4b800000 = 1266679808
var TWO_24_WORD = 0x4b800000 >>> 0; // asm type annotation

// High and low parts of π in single-precision floating-point format:
var PI_HIGH = f32( 3.14160156 );    // 0x40491000
var PI_LOW = f32( -8.90890988e-6 ); // 0xb715777a

// Mask for extracting the high 16 bits of a 32-bit integer:
var HIGH_16_MASK = 0xffff0000 >>> 0; // asm type annotation

// Mask for extracting the exponent bits of a 32-bit float:
var FLOAT32_EXPONENT_FIELD_MASK = 0xff >>> 0; // asm type annotation

var TWO_23 = f32( 8388608 ); // 2^23
var TWO_N23 = f32( 1.1920928955078125e-7 ); // 2^-23

var NEG_ONE = f32( -1.0 );
var ZERO = f32( 0.0 );
var HALF = f32( 0.5 );
var ONE = f32( 1.0 );


// MAIN //

/**
* Simultaneously computes the sine and cosine of a single-precision floating-point number times π and assigns the results to a provided output array.
*
* ## Notes
*
* -   The function computes `sin(πx)` and `cos(πx)` more accurately than the obvious approach, especially for large `x`.
*
* @param {number} x - input value
* @param {Collection} out - output array
* @param {integer} stride - output array stride
* @param {NonNegativeInteger} offset - output array index offset
* @returns {Collection} output array
*
* @example
* var v = sincospif( 0.0, [ 0.0, 0.0 ], 1, 0 );
* // returns [ 0.0, 1.0 ]
*
* @example
* var v = sincospif( 0.5, [ 0.0, 0.0 ], 1, 0 );
* // returns [ 1.0, 0.0 ]
*
* @example
* var v = sincospif( 0.1, [ 0.0, 0.0 ], 1, 0 );
* // returns [ ~0.309, ~0.951 ]
*
* @example
* var v = sincospif( NaN, [ 0.0, 0.0 ], 1, 0 );
* // returns [ NaN, NaN ]
*/
function sincospif( x, out, stride, offset ) {
	var tmp;
	var hx;
	var ix;
	var ax;
	var fx;
	var hi;
	var lo;
	var j0;
	var s;

	x = f32( x );
	hx = toWordf( x );
	ix = ( hx & FLOAT32_ABS_MASK ) >>> 0; // asm type annotation
	ax = fromWordf( ix ); // asm type annotation

	// Case: |x| < 1
	if ( ix < ONE_WORD ) {
		// Case: |x| < 0.25
		if ( ix < QUARTER_WORD ) {
			// Case: |x| < 2^-14
			if ( ix < SMALL_WORD ) {
				if ( x === 0.0 ) {
					out[ offset ] = x;
					out[ offset + stride ] = ONE;
					return out;
				}
				kernelSincosf( PI * ax, out, stride, offset );

				// Compute sin(πx) via argument scaling in order to avoid a loss of precision (mirrors the original FreeBSD implementation, which performs each operation in single-precision arithmetic):
				hi = fromWordf( hx & HIGH_16_MASK );
				hi = f32( hi * TWO_23 );
				lo = f32( f32( x * TWO_23 ) - hi );
				s = f32( f32( f32( PI_LOW+PI_HIGH )*lo ) + f32( PI_LOW*hi ) );
				s = f32( s + f32( PI_HIGH*hi ) );
				out[ offset ] = f32( s * TWO_N23 );
				return out;
			}
			kernelSincosf( PI * ax, out, stride, offset );
			if ( hx & FLOAT32_SIGN_MASK ) {
				out[ offset ] = -out[ offset ];
			}
			return out;
		}
		// Case: |x| < 0.5
		if ( ix < HALF_WORD ) {
			kernelSincosf( PI * f32( HALF - ax ), out, stride, offset );
			tmp = out[ offset ];
			out[ offset ] = out[ offset + stride ];
			out[ offset + stride ] = tmp;
		} else if ( ix === HALF_WORD ) { // Case: |x| == 0.5, in which case sin(πx) is ±1 and cos(πx) is +0
			out[ offset ] = ONE;
			out[ offset + stride ] = ZERO;
		} else if ( ix < THREE_QUARTER_WORD ) { // Case: |x| < 0.75
			kernelSincosf( PI * f32( ax - HALF ), out, stride, offset );
			tmp = out[ offset ];
			out[ offset ] = out[ offset + stride ];
			out[ offset + stride ] = -tmp;
		} else {
			kernelSincosf( PI * f32( ONE - ax ), out, stride, offset );
			out[ offset + stride ] = -out[ offset + stride ];
		}
		if ( hx & FLOAT32_SIGN_MASK ) {
			out[ offset ] = -out[ offset ];
		}
		return out;
	}
	// Case: 1 <= |x| < 2^23
	if ( ix < TWO_23_WORD ) {
		// Fast floor by bitwise manipulation:
		j0 = ( ( ix >> FLOAT32_NUM_SIGNIFICAND_BITS ) & FLOAT32_EXPONENT_FIELD_MASK ) - FLOAT32_EXPONENT_BIAS; // eslint-disable-line max-len
		ix &= ~( FLOAT32_SIGNIFICAND_MASK >> j0 );
		fx = fromWordf( ix );

		ax = f32( ax - fx );
		ix = toWordf( ax );

		j0 = float32ToUint32( fx );

		// Case: x is an integer, in which case sin(πx) is ±0 and cos(πx) is ±1...
		if ( ix === 0 ) {
			out[ offset ] = copysignf( ZERO, x );
			out[ offset + stride ] = ( j0 & 1 ) ? NEG_ONE : ONE;
			return out;
		}
		// Case: the fractional part of |x| is 0.5, in which case sin(πx) is ±1 and cos(πx) is +0...
		if ( ix === HALF_WORD ) {
			s = ( j0 & 1 ) ? NEG_ONE : ONE;
			out[ offset ] = ( hx & FLOAT32_SIGN_MASK ) ? -s : s;
			out[ offset + stride ] = ZERO;
			return out;
		}
		// Case: |x| < 0.5
		if ( ix < HALF_WORD ) {
			// Case: |x| < 0.25
			if ( ix < QUARTER_WORD ) {
				kernelSincosf( PI * ax, out, stride, offset );
			} else {
				kernelSincosf( PI * f32( HALF - ax ), out, stride, offset );
				tmp = out[ offset ];
				out[ offset ] = out[ offset + stride ];
				out[ offset + stride ] = tmp;
			}
		} else if ( ix < THREE_QUARTER_WORD ) { // Case: |x| < 0.75
			kernelSincosf( PI * f32( ax - HALF ), out, stride, offset );
			tmp = out[ offset ];
			out[ offset ] = out[ offset + stride ];
			out[ offset + stride ] = -tmp;
		} else {
			kernelSincosf( PI * f32( ONE - ax ), out, stride, offset );
			out[ offset + stride ] = -out[ offset + stride ];
		}
		if ( j0 & 1 ) {
			out[ offset ] = -out[ offset ];
			out[ offset + stride ] = -out[ offset + stride ];
		}
		if ( hx & FLOAT32_SIGN_MASK ) {
			out[ offset ] = -out[ offset ];
		}
		return out;
	}
	// Case: x is NaN or infinity
	if ( ix >= FLOAT32_EXPONENT_MASK ) {
		out[ offset ] = NaN;
		out[ offset + stride ] = NaN;
		return out;
	}
	// Case: 2^23 <= |x| < 2^24, in which case x is an integer whose parity is given by the lowest bit of the word...
	if ( ix < TWO_24_WORD ) {
		out[ offset ] = copysignf( ZERO, x );
		out[ offset + stride ] = ( ix & 1 ) ? NEG_ONE : ONE;
		return out;
	}
	// Case: |x| >= 2^24 is always an even integer, so sin(πx) is ±0 and cos(πx) is 1...
	out[ offset ] = copysignf( ZERO, x );
	out[ offset + stride ] = ONE;
	return out;
}


// EXPORTS //

export default sincospif;
